func Test_SourceString(t *testing.T) {
	require.Equal(t, "oci", (&SnapshotStore{}).String())
}

func Test_SourceSubscribe(t *testing.T) {
	ch := make(chan struct{})
	store, target := testStore(t, WithPollOptions(
		fs.WithInterval(time.Second),
		fs.WithNotify(t, func(modified bool) {
			if modified {
				close(ch)
			}
		}),
	))

	ctx := context.Background()

	require.NoError(t, store.View(func(s storage.ReadOnlyStore) error {
		_, err := s.GetNamespace(ctx, "production")
		require.NoError(t, err)

		_, err = s.GetFlag(ctx, "production", "foo")
		require.Error(t, err, "should error as flag should not exist yet")

		return nil
	}))

	updateRepoContents(t, target,
		layer(
			"production",
			`{"namespace":"production","flags":[{"key":"foo","name":"Foo"}]}`,
			fliptoci.MediaTypeFliptNamespace,
		),
	)

	t.Log("waiting for new snapshot")

	// assert matching state
	select {
	case <-ch:
	case <-time.After(time.Minute):
		t.Fatal("timed out waiting for snapshot")
	}

	t.Log("received new snapshot")

	require.NoError(t, store.View(func(s storage.ReadOnlyStore) error {
		_, err := s.GetFlag(ctx, "production", "foo")
		require.NoError(t, err)
		return nil
	}))
}

func testStore(t *testing.T, opts ...containers.Option[SnapshotStore]) (*SnapshotStore, oras.Target) {
	t.Helper()

	target, dir, repo := testRepository(t,
		layer("production", `{"namespace":"production"}`, fliptoci.MediaTypeFliptNamespace),
	)

	store, err := fliptoci.NewStore(zaptest.NewLogger(t), dir)
	require.NoError(t, err)

	ref, err := fliptoci.ParseReference(fmt.Sprintf("flipt://local/%s:latest", repo))
	require.NoError(t, err)

	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)

	source, err := NewSnapshotStore(ctx,
		zaptest.NewLogger(t),
		store,
		ref,
		opts...)
	require.NoError(t, err)

	return source, target
}

func layer(ns, payload, mediaType string) func(*testing.T, oras.Target) v1.Descriptor {
	return func(t *testing.T, store oras.Target) v1.Descriptor {
		t.Helper()

		desc := v1.Descriptor{
			Digest:    digest.FromString(payload),
			Size:      int64(len(payload)),
			MediaType: mediaType,
			Annotations: map[string]string{
				fliptoci.AnnotationFliptNamespace: ns,
			},
		}

		require.NoError(t, store.Push(context.TODO(), desc, bytes.NewReader([]byte(payload))))

		return desc
	}
}

func testRepository(t *testing.T, layerFuncs ...func(*testing.T, oras.Target) v1.Descriptor) (oras.Target, string, string) {
	t.Helper()

	var (
		repository = "testrepo"
		dir        = t.TempDir()
	)

	store, err := oci.New(path.Join(dir, repository))
	require.NoError(t, err)

	store.AutoSaveIndex = true

	updateRepoContents(t, store, layerFuncs...)

	return store, dir, repository
}

func updateRepoContents(t *testing.T, target oras.Target, layerFuncs ...func(*testing.T, oras.Target) v1.Descriptor) {
	t.Helper()
	ctx := context.TODO()

	var layers []v1.Descriptor
	for _, fn := range layerFuncs {
		layers = append(layers, fn(t, target))
	}

	desc, err := oras.PackManifest(ctx, target, oras.PackManifestVersion1_1_RC4, fliptoci.MediaTypeFliptFeatures, oras.PackManifestOptions{
		ManifestAnnotations: map[string]string{},
		Layers:              layers,

package azblob

import (
	"context"
	"os"
	"testing"
	"time"

	"github.com/Azure/azure-sdk-for-go/sdk/storage/azblob"
	"github.com/Azure/azure-sdk-for-go/sdk/storage/azblob/bloberror"
	"github.com/stretchr/testify/require"
	"go.flipt.io/flipt/internal/containers"
	"go.flipt.io/flipt/internal/storage"
	"go.flipt.io/flipt/internal/storage/fs"
	"go.uber.org/zap/zaptest"
)

const testContainer = "testdata"

var aruziteURL = os.Getenv("TEST_AZURE_ENDPOINT")

func Test_Store_String(t *testing.T) {
	require.Equal(t, "azblob", (&SnapshotStore{}).String())
}

func Test_Store(t *testing.T) {
	ch := make(chan struct{})
	store, skip := testStore(t, WithPollOptions(
		fs.WithInterval(time.Second),
		fs.WithNotify(t, func(modified bool) {
			if modified {
				close(ch)
			}
		}),
	))
	if skip {
		return
	}

	client := testClient(t)

	// flag shouldn't be present until we update it
	require.Error(t, store.View(func(s storage.ReadOnlyStore) error {
		_, err := s.GetFlag(context.TODO(), "production", "foo")
		return err
	}), "flag should not be defined yet")

	updated := []byte(`namespace: production
flags:
    - key: foo
      name: Foo`)

	// update features.yml
	_, err := client.UploadBuffer(context.TODO(), store.container, "features.yml", updated, nil)
	require.NoError(t, err)

	// assert matching state
	select {
	case <-ch:
	case <-time.After(time.Minute):
		t.Fatal("timed out waiting for update")
	}

	t.Log("received new snapshot")

	require.NoError(t, store.View(func(s storage.ReadOnlyStore) error {
		_, err = s.GetNamespace(context.TODO(), "production")
		if err != nil {
			return err
		}

		_, err = s.GetFlag(context.TODO(), "production", "foo")

		return err
	}))

}

func testClient(t *testing.T) *azblob.Client {
	t.Helper()
	account := os.Getenv("AZURE_STORAGE_ACCOUNT")
	sharedKey := os.Getenv("AZURE_STORAGE_KEY")
	credentials, err := azblob.NewSharedKeyCredential(account, sharedKey)
	require.NoError(t, err)
	client, err := azblob.NewClientWithSharedKeyCredential(aruziteURL, credentials, nil)
	require.NoError(t, err)
	return client
}

func testStore(t *testing.T, opts ...containers.Option[SnapshotStore]) (*SnapshotStore, bool) {
	t.Helper()
	if aruziteURL == "" {
		t.Skip("Set non-empty TEST_AZURE_ENDPOINT env var to run this test.")
		return nil, true
	}
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)
	client := testClient(t)
	// create container
	_, err := client.CreateContainer(ctx, testContainer, nil)
	if err != nil {
		if !bloberror.HasCode(err, bloberror.ContainerAlreadyExists) {
			require.NoError(t, err)
		}
	}
	_, err = client.UploadBuffer(ctx, testContainer, ".flipt.yml", []byte(`namespace: production`), nil)
	require.NoError(t, err)

	source, err := NewSnapshotStore(ctx, zaptest.NewLogger(t), testContainer,
		append([]containers.Option[SnapshotStore]{
			WithEndpoint(aruziteURL),
		},
			opts...)...,
	)
	require.NoError(t, err)
	return source, false
}

package fs

import (
	"context"
	"errors"
	"fmt"
	"path"

	"go.flipt.io/flipt/internal/storage"
	"go.flipt.io/flipt/rpc/flipt"
)

var (
	_ storage.Store = (*Store)(nil)

	// ErrNotImplemented is returned when a method has intentionally not been implemented
	// This is usually reserved for the store write actions when the store is read-only
	// but still needs to implement storage.Store
	ErrNotImplemented = errors.New("not implemented")
)

// SnapshotStore is a type which has a single function View.
// View is a functional transaction interface for reading a snapshot
// during the lifetime of a supplied function.
type SnapshotStore interface {
	// View accepts a function which takes a *StoreSnapshot.
	// The SnapshotStore will supply a snapshot which is valid
	// for the lifetime of the provided function call.
	View(func(storage.ReadOnlyStore) error) error
	fmt.Stringer
}

// Store embeds a StoreSnapshot and wraps the Store methods with a read-write mutex
// to synchronize reads with atomic replacements of the embedded snapshot.
type Store struct {
	viewer SnapshotStore
}

func NewStore(viewer SnapshotStore) *Store {
	return &Store{viewer: viewer}
}

func (s *Store) String() string {
	return path.Join("declarative", s.viewer.String())
}

func (s *Store) GetFlag(ctx context.Context, namespaceKey string, key string) (flag *flipt.Flag, err error) {
	if namespaceKey == "" {
